(function(){
  var n = scope.n_raw;
  var d = scope.d_raw;
  if (n >= d) d = n + scope.k;
  var g = gcd(n, d);
  n = n / g;
  d = d / g;
  var k = scope.k;
  var num = n * k;
  var den = d * k;
  var simp = simplifyFrac(num, den);
  return { num: num, den: den, ans: simp.str, g: k * g, n: n, d: d };
})()

(function(){
  var isAdd = scope.op_idx === 0;
  var d1 = scope.d1, d2 = scope.d2;
  var n1 = scope.n1 % d1 || 1;
  var n2 = scope.n2 % d2 || 1;
  var common_d = (d1 * d2) / gcd(d1, d2);
  var num1 = n1 * (common_d / d1);
  var num2 = n2 * (common_d / d2);
  if (!isAdd && num1 < num2) {
    var tempN = n1; n1 = n2; n2 = tempN;
    var tempD = d1; d1 = d2; d2 = tempD;
    num1 = n1 * (common_d / d1);
    num2 = n2 * (common_d / d2);
  }
  var res_num = isAdd ? (num1 + num2) : (num1 - num2);
  var simp = simplifyFrac(res_num, common_d);
  return { n1: n1, d1: d1, n2: n2, d2: d2, num1: num1, num2: num2, res_num: res_num, common_d: common_d, op: isAdd ? '+' : '-', ans: simp.str };
})()

(function(){
  var isMult = scope.op_idx === 0;
  var n1 = scope.n1, d1 = scope.d1, n2 = scope.n2, d2 = scope.d2;
  var res_n = isMult ? (n1 * n2) : (n1 * d2);
  var res_d = isMult ? (d1 * d2) : (d1 * n2);
  var simp = simplifyFrac(res_n, res_d);
  return { n1: n1, d1: d1, n2: n2, d2: d2, res_n: res_n, res_d: res_d, isMult: isMult, ans: simp.str };
})()

(function(){
  var pools = [
    [{n:1,d:5,v:0.2}, {n:1,d:4,v:0.25}, {n:1,d:3,v:0.333}],
    [{n:1,d:10,v:0.1}, {n:3,d:5,v:0.6}, {n:3,d:4,v:0.75}],
    [{n:1,d:6,v:0.167}, {n:2,d:5,v:0.4}, {n:2,d:3,v:0.667}],
    [{n:1,d:8,v:0.125}, {n:3,d:8,v:0.375}, {n:5,d:8,v:0.625}],
    [{n:1,d:9,v:0.111}, {n:4,d:9,v:0.444}, {n:7,d:9,v:0.778}]
  ];
  var pool = pools[scope.seed];
  var isAsc = scope.order_type === 0;
  var sorted = pool.slice().sort(function(a, b){ return isAsc ? a.v - b.v : b.v - a.v; });
  var origStr = pool.map(function(f){ return '\\frac{' + f.n + '}{' + f.d + '}'; }).join(', ');
  var ansStr = sorted.map(function(f){ return f.n + '/' + f.d; }).join(', ');
  var stepStr = sorted.map(function(f){ return '\\frac{' + f.n + '}{' + f.d + '}'; }).join(', ');
  return { origStr: origStr, ansStr: ansStr, stepStr: stepStr, word: isAsc ? 'ascending' : 'descending' };
})()

(function(){
  var t = scope.op_type;
  var n1 = scope.n1, d1 = scope.d1, n2 = scope.n2, d2 = scope.d2;
  var expr, ans_n, ans_d;
  if (t === 0) {
    expr = '\\left(-\\frac{' + n1 + '}{' + d1 + '}\\right) \\times \\left(-\\frac{' + n2 + '}{' + d2 + '}\\right)';
    ans_n = n1 * n2;
    ans_d = d1 * d2;
  } else if (t === 1) {
    expr = '\\frac{' + n1 + '}{' + d1 + '} \\times \\left(-\\frac{' + n2 + '}{' + d2 + '}\\right)';
    ans_n = -(n1 * n2);
    ans_d = d1 * d2;
  } else {
    expr = '\\left(-\\frac{' + n1 + '}{' + d1 + '}\\right) \\div \\left(-\\frac{' + n2 + '}{' + d2 + '}\\right)';
    ans_n = n1 * d2;
    ans_d = d1 * n2;
  }
  var simp = simplifyFrac(ans_n, ans_d);
  return { expr: expr, ans: simp.str };
})()

(function(){
  var t = scope.type_idx;
  if (t === 0) {
    return {
      expr: '1 + \\frac{2}{3} \\times \\left(-\\frac{1}{4} + \\frac{1}{8}\\right)',
      step1: '-\\frac{1}{4} + \\frac{1}{8} = -\\frac{1}{8}',
      step2: '\\frac{2}{3} \\times \\left(-\\frac{1}{8}\\right) = -\\frac{1}{12}',
      ans: '11/12'
    };
  } else {
    return {
      expr: '5 + \\left(\\frac{2}{5} - \\frac{1}{10}\\right) \\div \\left(-\\frac{1}{10}\\right)',
      step1: '\\frac{2}{5} - \\frac{1}{10} = \\frac{3}{10}',
      step2: '\\left(\\frac{3}{10}\\right) \\div \\left(-\\frac{1}{10}\\right) = -3',
      ans: '2'
    };
  }
})()
